// Appends Facial Makeup ids 501-525 (25) and closes the array
import { readFileSync, writeFileSync } from 'fs'
import { fileURLToPath } from 'url'
import { join, dirname } from 'path'
const __dirname = dirname(fileURLToPath(import.meta.url))
const FILE = join(__dirname, '../src/esthi-questions.js')

const fmT=`"Facial Makeup"`, fmTes=`"Maquillaje Facial"`, fmPt=`"Facial Makeup"`, fmPtes=`"Maquillaje Facial"`

function fmt(q) {
  return `  { id: ${q.id}, topic: ${fmT}, topic_es: ${fmTes}, psi_topic: ${fmPt}, psi_topic_es: ${fmPtes}, question: ${JSON.stringify(q.question)}, question_es: ${JSON.stringify(q.question_es)}, options: ${JSON.stringify(q.options)}, options_es: ${JSON.stringify(q.options_es)}, correct: ${q.correct}, explanation: ${JSON.stringify(q.explanation)} },`
}

const FM = [
  { id: 501, question: "Which best describes the purpose of using a primer before applying foundation in a facial makeup application?", question_es: "¿Cuál describe mejor el propósito de usar un primer antes de aplicar la base de maquillaje en una aplicación de maquillaje facial?", options: ["To create a smoother surface, help minimize the appearance of pores or fine lines, and support longer-lasting wear of the makeup applied over it", "To permanently close pores so they never become visible again under any circumstances", "To replace the need for cleansing or moisturizing the skin before makeup application", "To provide a substitute for sunscreen that offers equal or superior sun protection"], options_es: ["Crear una superficie más uniforme, ayudar a minimizar la apariencia de los poros o las líneas finas, y favorecer una mayor duración del maquillaje aplicado sobre ella", "Cerrar permanentemente los poros para que nunca vuelvan a ser visibles bajo ninguna circunstancia", "Reemplazar la necesidad de limpiar o hidratar la piel antes de la aplicación del maquillaje", "Proporcionar un sustituto del protector solar que ofrezca una protección solar igual o superior"], correct: 0, explanation: "Primer is typically applied after skincare and before foundation to create a smoother canvas, temporarily minimize the visual appearance of pores and fine lines, and help makeup adhere better and last longer. It does not permanently alter pore size, replace basic skincare steps like cleansing and moisturizing, or substitute for dedicated sun protection." },
  { id: 502, question: "A client with oily skin asks the esthetician for guidance on selecting a foundation formula that will help their makeup look fresh throughout the day. Which response best reflects sound professional guidance?", question_es: "Un cliente con piel grasa le pide al esteticista orientación para elegir una fórmula de base de maquillaje que ayude a que su maquillaje se vea fresco durante todo el día. ¿Cuál respuesta refleja mejor una orientación profesional sólida?", options: ["Discussing options such as oil-free or matte-finish formulas, suggesting the use of a mattifying primer or setting product, and explaining that blotting throughout the day can help manage shine", "Recommending only the heaviest, fullest-coverage formula available regardless of the client's skin type or finish preference", "Telling the client that oily skin has no bearing whatsoever on which makeup formulas might suit them best", "Suggesting the client avoid wearing any makeup at all if they have oily skin"], options_es: ["Discutir opciones como fórmulas sin aceite o de acabado mate, sugerir el uso de un primer matificante o un producto fijador, y explicar que aplicar papel matificante durante el día puede ayudar a controlar el brillo", "Recomendar únicamente la fórmula más pesada y de mayor cobertura disponible sin importar el tipo de piel del cliente o su preferencia de acabado", "Decirle al cliente que la piel grasa no tiene ninguna relación con qué fórmulas de maquillaje podrían sentarle mejor", "Sugerirle al cliente que evite usar maquillaje por completo si tiene piel grasa"], explanation: "Thoughtful guidance for oily skin might include discussing oil-free or matte-finish foundation options, mattifying primers, and setting powders or sprays, as well as practical tips like blotting to manage midday shine — tailoring recommendations to the client's specific skin type and goals rather than offering a one-size-fits-all answer or dismissing the relevance of skin type." },
  { id: 503, question: "Which best describes an appropriate technique for applying concealer to address dark circles under the eyes?", question_es: "¿Cuál describe mejor una técnica apropiada para aplicar corrector para tratar las ojeras debajo de los ojos?", options: ["Choosing a shade and undertone appropriate for neutralizing the discoloration and for the surrounding skin, applying a small amount precisely where needed, and blending gently to avoid disturbing the delicate under-eye area", "Applying the heaviest possible layer of the darkest available shade directly under the eyes regardless of the client's natural coloring", "Using a rough, vigorous rubbing motion to blend the product into the thin under-eye skin", "Skipping any consideration of undertone or shade-matching, since concealer color has no effect on how discoloration appears once applied"], options_es: ["Elegir un tono y subtono apropiados para neutralizar la decoloración y para la piel circundante, aplicar una pequeña cantidad precisamente donde se necesita, y difuminar suavemente para no alterar el área delicada debajo de los ojos", "Aplicar la capa más pesada posible del tono más oscuro disponible directamente debajo de los ojos sin importar la coloración natural del cliente", "Usar un movimiento de frotamiento áspero y vigoroso para difuminar el producto en la piel delgada debajo de los ojos", "Omitir cualquier consideración sobre el subtono o la combinación de tonos, ya que el color del corrector no tiene ningún efecto en cómo aparece la decoloración una vez aplicado"], explanation: "The under-eye area has thin, delicate skin, so a gentle approach matters. Selecting a concealer shade and undertone suited both to neutralizing the specific discoloration and to blending naturally with surrounding skin, applying it precisely in a thin layer, and blending with light, gentle motions (such as gentle patting) helps achieve a natural-looking result without irritating the area." },
  { id: 504, question: "A client asks why an esthetician might recommend setting makeup with a translucent powder or setting spray after application. An accurate, helpful explanation would note that:", question_es: "Un cliente pregunta por qué un esteticista podría recomendar fijar el maquillaje con un polvo translúcido o un spray fijador después de la aplicación. Una explicación precisa y útil señalaría que:", options: ["Setting products can help reduce shine, lock the makeup in place, and support longer wear throughout the day, though the right choice depends on the client's skin type, the look they want, and the products used", "Setting products are required by law for every makeup application performed in a licensed establishment", "Setting products permanently bond makeup to the skin so that it never needs to be removed by any method", "Setting products eliminate any need to consider the client's skin type when choosing other makeup products"], options_es: ["Los productos fijadores pueden ayudar a reducir el brillo, fijar el maquillaje en su lugar, y favorecer una mayor duración durante el día, aunque la elección adecuada depende del tipo de piel del cliente, el aspecto que desea y los productos utilizados", "Los productos fijadores son requeridos por ley para cada aplicación de maquillaje realizada en un establecimiento con licencia", "Los productos fijadores se unen permanentemente al maquillaje con la piel para que nunca necesite eliminarse por ningún método", "Los productos fijadores eliminan cualquier necesidad de considerar el tipo de piel del cliente al elegir otros productos de maquillaje"], explanation: "Setting powders and sprays can help control shine, minimize transfer, and extend the wear time of a makeup look — but they are a styling choice based on the client's skin type, desired finish, and the rest of the products used, not a legal requirement or a way to make makeup permanent or skin-type-irrelevant." },
  { id: 505, question: "Which best describes a thoughtful approach to selecting eyeshadow colors for a client during a consultation?", question_es: "¿Cuál describe mejor un enfoque reflexivo para seleccionar colores de sombra de ojos para un cliente durante una consulta?", options: ["Discussing the client's preferences, the occasion, and how different colors may complement their eye color and overall look, while helping them understand general color theory concepts in approachable terms", "Selecting colors solely based on what the esthetician personally likes to wear, without asking about the client's preferences", "Choosing the same exact color palette for every client regardless of their preferences, eye color, or the occasion", "Avoiding any conversation with the client about their preferences so the esthetician can finish the consultation more quickly"], options_es: ["Discutir las preferencias del cliente, la ocasión, y cómo diferentes colores pueden complementar su color de ojos y su apariencia general, mientras se ayuda a entender conceptos generales de la teoría del color en términos accesibles", "Seleccionar colores únicamente según lo que el esteticista personalmente prefiere usar, sin preguntar sobre las preferencias del cliente", "Elegir exactamente la misma paleta de colores para cada cliente sin importar sus preferencias, color de ojos o la ocasión", "Evitar cualquier conversación con el cliente sobre sus preferencias para que el esteticista pueda terminar la consulta más rápidamente"], explanation: "A good consultation centers the client: understanding their preferences, the occasion for the look, and offering approachable explanations of how certain colors may complement their features (such as how complementary colors on the color wheel can make eye color stand out). This collaborative, individualized process leads to a result the client will feel confident wearing — unlike imposing the esthetician's personal taste or applying a uniform approach to every client." },
  { id: 506, question: "Which best describes why an esthetician should use clean, sanitized brushes and applicators — and avoid double-dipping into shared makeup products — during a facial makeup application?", question_es: "¿Cuál describe mejor por qué un esteticista debe usar brochas y aplicadores limpios y desinfectados — y evitar volver a sumergirlos en productos de maquillaje compartidos — durante una aplicación de maquillaje facial?", options: ["To reduce the risk of transferring bacteria, oils, and other contaminants between the client's skin and shared products, helping protect both that client and any future clients who may use the same products", "Because color payoff is improved when brushes are reused without any cleaning between different clients", "Because using the same brush on every client guarantees a more consistent result regardless of sanitation considerations", "Because sanitizing brushes and applicators is solely a matter of extending the lifespan of the tools and has no bearing on health or safety"], options_es: ["Para reducir el riesgo de transferir bacterias, aceites y otros contaminantes entre la piel del cliente y los productos compartidos, ayudando a proteger tanto a ese cliente como a cualquier cliente futuro que pueda usar los mismos productos", "Porque el rendimiento del color mejora cuando las brochas se reutilizan sin ninguna limpieza entre diferentes clientes", "Porque usar la misma brocha en cada cliente garantiza un resultado más consistente sin importar las consideraciones de saneamiento", "Porque desinfectar las brochas y los aplicadores es únicamente una cuestión de prolongar la vida útil de las herramientas y no tiene relación con la salud o la seguridad"], explanation: "Makeup brushes and applicators that touch a client's skin can pick up bacteria, oils, and other residue. If reused without proper cleaning — especially when dipped directly into shared product containers — they can transfer contaminants to that product, creating a cross-contamination risk for the current client and for any future client who later uses the same product. Using clean, sanitized tools and single-use applicators where appropriate is a fundamental infection control practice, not merely a matter of extending tool lifespan or improving payoff." },
  { id: 507, question: "A client asks the esthetician to explain, in simple terms, why their foundation shade might need to be adjusted between seasons. An accurate, appropriately scoped explanation would note that:", question_es: "Un cliente le pide al esteticista que explique, en términos simples, por qué podría ser necesario ajustar el tono de su base de maquillaje entre estaciones. Una explicación precisa y con el alcance apropiado señalaría que:", options: ["Skin tone can shift somewhat with factors like sun exposure across different seasons, so periodically reassessing the shade match can help keep the makeup looking natural", "Foundation shade never needs any adjustment for any client at any point because skin tone is permanently fixed from birth", "Foundation shades are designed to automatically change their own color to match any skin tone without any input from the wearer", "Seasonal shade changes are purely a marketing concept and have no connection to any real change in the client's skin"], options_es: ["El tono de la piel puede cambiar algo debido a factores como la exposición al sol en diferentes estaciones, por lo que reevaluar periódicamamente la combinación de tonos puede ayudar a que el maquillaje se vea natural", "El tono de la base de maquillaje nunca necesita ningún ajuste para ningún cliente en ningún momento porque el tono de la piel está permanentemente fijo desde el nacimiento", "Los tonos de base de maquillaje están diseñados para cambiar automáticamente su propio color y combinar con cualquier tono de piel sin ninguna intervención de quien lo usa", "Los cambios estacionales de tono son puramente un concepto de marketing y no tienen ninguna conexión con ningún cambio real en la piel del cliente"], explanation: "A person's visible skin tone can shift somewhat over time due to factors such as seasonal changes in sun exposure. Periodically reassessing foundation shade match — rather than assuming it stays exactly the same indefinitely — helps keep makeup looking natural and well-blended. This is a simple, accurate, and appropriately scoped explanation that respects the underlying skin science without overstating or dismissing it." },
  { id: 508, question: "Which best describes an appropriate way for an esthetician to handle a situation where a client requests a dramatic makeup look that the esthetician believes may not suit the stated occasion (such as a conservative daytime professional event)?", question_es: "¿Cuál describe mejor una manera apropiada para que un esteticista maneje una situación en la que un cliente solicita un look de maquillaje dramático que el esteticista cree que podría no ser adecuado para la ocasión declarada (como un evento profesional diurno conservador)?", options: ["Respectfully sharing professional perspective on how the look might be perceived in that context, offering alternative suggestions that could achieve the client's general goals, and ultimately respecting the client's final decision", "Refusing outright to perform any makeup application that does not match the esthetician's personal opinion of what is appropriate", "Silently performing the requested look without sharing any professional perspective, even if the esthetician has genuinely useful input to offer", "Performing a completely different look than what the client requested, without discussing it with them first"], options_es: ["Compartir respetuosamente una perspectiva profesional sobre cómo podría percibirse el look en ese contexto, ofrecer sugerencias alternativas que podrían lograr los objetivos generales del cliente, y en última instancia respetar la decisión final del cliente", "Negarse rotundamente a realizar cualquier aplicación de maquillaje que no coincida con la opinión personal del esteticista sobre lo que es apropiado", "Realizar en silencio el look solicitado sin compartir ninguna perspectiva profesional, incluso si el esteticista tiene información genuinamente útil para ofrecer", "Realizar un look completamente diferente al solicitado por el cliente, sin discutirlo con ellos primero"], explanation: "When a client's request and the esthetician's professional judgment about a particular context seem to be in tension, the most respectful and useful approach is open dialogue: sharing relevant perspective, offering alternatives that might still satisfy the client's underlying goals, and ultimately respecting the client's autonomy to make the final decision about their own appearance — rather than refusing service, withholding helpful input, or unilaterally substituting a different look." },
  { id: 509, question: "Which best describes the purpose of using a lip liner before applying lipstick or gloss in a facial makeup application?", question_es: "¿Cuál describe mejor el propósito de usar un delineador de labios antes de aplicar lápiz labial o brillo en una aplicación de maquillaje facial?", options: ["To help define and balance the shape of the lips, provide a guide for color application, and support longer wear of the lip color applied over it", "To permanently reshape the structure of the lips so that no other lip products will ever be necessary again", "To replace the need for any lip color product entirely in a complete makeup look", "To provide medical-grade treatment for any underlying lip condition the client may have"], options_es: ["Ayudar a definir y equilibrar la forma de los labios, proporcionar una guía para la aplicación del color, y favorecer una mayor duración del color labial aplicado sobre él", "Cambiar permanentemente la estructura de los labios para que nunca más sea necesario ningún otro producto labial", "Reemplazar por completo la necesidad de cualquier producto de color labial en un look de maquillaje completo", "Proporcionar un tratamiento de grado médico para cualquier afección subyacente de los labios que el cliente pueda tener"], explanation: "Lip liner is a cosmetic tool that can help visually balance lip shape, create a clean edge that guides where color is applied, and help lip color stay in place longer. It is a temporary cosmetic enhancement — it does not permanently alter lip structure, replace the lip color product itself, or serve any medical or therapeutic purpose." },
  { id: 510, question: "A client mentions they have a known allergy to a specific cosmetic ingredient and asks the esthetician to check the products being considered for today's makeup application. Which is the most appropriate response?", question_es: "Un cliente menciona que tiene una alergia conocida a un ingrediente cosmético específico y le pide al esteticista que revise los productos que se están considerando para la aplicación de maquillaje de hoy. ¿Cuál es la respuesta más apropiada?", options: ["Take the allergy seriously, review available ingredient information for the products under consideration, avoid any product containing the ingredient in question, and discuss alternative options with the client", "Proceed with the originally planned products without reviewing their ingredients, since cosmetic allergies are extremely rare and unlikely to be relevant", "Tell the client that checking ingredient lists is not a responsibility of the esthetician under any circumstances", "Apply a small amount of every product under consideration directly to the client's face to observe whether a reaction develops"], options_es: ["Tomar la alergia en serio, revisar la información disponible sobre los ingredientes de los productos en consideración, evitar cualquier producto que contenga el ingrediente en cuestión, y discutir opciones alternativas con el cliente", "Proceder con los productos originalmente planeados sin revisar sus ingredientes, ya que las alergias cosméticas son extremadamente raras y poco probables de ser relevantes", "Decirle al cliente que revisar las listas de ingredientes no es una responsabilidad del esteticista bajo ninguna circunstancia", "Aplicar una pequeña cantidad de cada producto en consideración directamente en el rostro del cliente para observar si se desarrolla una reacción"], explanation: "A reported allergy to a specific ingredient is important safety information that should be taken seriously every time. The appropriate response is to check ingredient information for the products being considered, avoid anything containing the flagged ingredient, and work with the client to find suitable alternatives — not to proceed without checking, deflect responsibility, or deliberately expose the client's face to potential allergens to test for a reaction." },
  { id: 511, question: "Which best describes an appropriate technique for applying blush to complement a client's face shape and desired look?", question_es: "¿Cuál describe mejor una técnica apropiada para aplicar rubor para complementar la forma del rostro del cliente y el look deseado?", options: ["Considering the client's face shape and the overall effect they want (such as a more lifted or softer appearance), applying the product to the appropriate area of the cheek with light layering, and blending so the color transitions naturally into the surrounding skin", "Applying the same exact placement and amount of blush to every client regardless of their face shape or desired effect", "Applying as much product as possible in a single heavy layer to ensure the color is visible from a distance", "Avoiding any blending after application so the product remains in sharply visible patches on the cheeks"], options_es: ["Considerar la forma del rostro del cliente y el efecto general que desea (como una apariencia más levantada o más suave), aplicar el producto en el área apropiada de la mejilla con capas ligeras, y difuminar para que el color se transicione de manera natural hacia la piel circundante", "Aplicar exactamente la misma colocación y cantidad de rubor a cada cliente sin importar la forma de su rostro o el efecto deseado", "Aplicar la mayor cantidad de producto posible en una sola capa pesada para asegurar que el color sea visible desde la distancia", "Evitar cualquier difuminado después de la aplicación para que el producto permanezca en parches marcadamente visibles en las mejillas"], explanation: "Thoughtful blush application takes into account the individual's face shape and the look they're going for, places the product in a flattering area with light, buildable layers, and blends thoroughly so the color looks like a natural flush rather than an obvious patch of color. A uniform, heavy-handed, or unblended approach ignores the individualized nature of good makeup artistry." },
  { id: 512, question: "Which best describes the role of highlighter in a facial makeup application?", question_es: "¿Cuál describe mejor el papel del iluminador en una aplicación de maquillaje facial?", options: ["To add subtle light-reflecting brightness to areas of the face the client wants to visually emphasize, when used thoughtfully and in moderation as part of an overall look", "To completely replace foundation and concealer in any makeup application", "To permanently change the underlying structure or contours of the client's face", "To provide a substitute for skincare products such as moisturizer or sunscreen"], options_es: ["Agregar un brillo sutil que refleja la luz a las áreas del rostro que el cliente desea enfatizar visualmente, cuando se usa de manera reflexiva y con moderación como parte de un look general", "Reemplazar por completo la base de maquillaje y el corrector en cualquier aplicación de maquillaje", "Cambiar permanentemente la estructura o los contornos subyacentes del rostro del cliente", "Proporcionar un sustituto de productos de cuidado de la piel como la crema hidratante o el protector solar"], explanation: "Highlighter is a cosmetic product used to add subtle, light-catching brightness to areas of the face — often used to visually emphasize features the client wants to draw attention to, as part of a balanced overall look. It is a finishing touch that complements (not replaces) base products like foundation and concealer, has no permanent structural effect, and is not a substitute for skincare." },
  { id: 513, question: "A client asks the esthetician why it might be helpful to apply makeup in good, natural lighting whenever possible. The most accurate, professionally appropriate explanation is:", question_es: "Un cliente le pregunta al esteticista por qué podría ser útil aplicar el maquillaje con buena luz natural siempre que sea posible. La explicación más precisa y profesionalmente apropiada es:", options: ["Natural or well-balanced lighting tends to show true colors and blending more accurately than artificial or dim lighting, helping ensure the final look appears as intended in a variety of everyday settings", "Lighting has no effect whatsoever on how makeup colors or blending appear once the product has been applied", "Makeup should only ever be applied under colored stage lighting to achieve any acceptable result", "Natural lighting permanently changes the chemical composition of makeup products to make them last longer"], options_es: ["La luz natural o bien equilibrada tiende a mostrar los colores verdaderos y el difuminado de manera más precisa que la luz artificial o tenue, ayudando a asegurar que el look final se vea como se pretende en una variedad de entornos cotidianos", "La iluminación no tiene ningún efecto en cómo aparecen los colores del maquillaje o el difuminado una vez que el producto ha sido aplicado", "El maquillaje solo debe aplicarse bajo luces de escenario de colores para lograr cualquier resultado aceptable", "La luz natural cambia permanentemente la composición química de los productos de maquillaje para que duren más"], explanation: "Lighting can significantly affect how colors and blending appear — artificial or dim lighting can sometimes mask unevenness or distort true color that becomes more apparent in natural light. Applying makeup in natural or well-balanced lighting helps achieve a result that looks accurate and well-blended across the variety of settings the client will move through during the day." },
  { id: 514, question: "Which best describes why an esthetician should ask a client about any planned activities (such as attending an outdoor event in hot weather) before finalizing product and technique choices for a makeup application?", question_es: "¿Cuál describe mejor por qué un esteticista debe preguntar a un cliente sobre cualquier actividad planificada (como asistir a un evento al aire libre en clima caluroso) antes de finalizar las elecciones de productos y técnicas para una aplicación de maquillaje?", options: ["Understanding the client's planned environment and activities can help guide choices such as long-wear or waterproof formulas, oil-control products, or particular setting techniques that are more likely to hold up well in those conditions", "Planned activities have no possible bearing on which makeup products or techniques would be most suitable for a client", "The esthetician should choose products solely based on what is most convenient to apply quickly, regardless of how the client will be using the look afterward", "Asking about a client's planned activities is solely a matter of casual conversation and serves no practical purpose in product selection"], options_es: ["Comprender el entorno y las actividades planificadas del cliente puede ayudar a guiar elecciones como fórmulas de larga duración o resistentes al agua, productos de control de grasa, o técnicas de fijación particulares que probablemente se mantengan mejor en esas condiciones", "Las actividades planificadas no tienen ninguna relación posible con qué productos o técnicas de maquillaje serían más adecuados para un cliente", "El esteticista debe elegir los productos únicamente según lo que sea más conveniente de aplicar rápidamente, sin importar cómo el cliente usará el look después", "Preguntar sobre las actividades planificadas de un cliente es únicamente una cuestión de conversación casual y no tiene ningún propósito práctico en la selección de productos"], explanation: "Knowing how and where a client will be using their makeup look — for example, an outdoor event in heat and humidity versus an indoor evening occasion — allows the esthetician to make more informed choices about formulas (such as long-wear or waterproof options), oil control, and setting techniques that are more likely to perform well in that specific context. This is practical, client-centered planning rather than idle conversation or convenience-driven shortcuts." },
  { id: 515, question: "Which best describes an appropriate way for an esthetician to remove makeup from a client's face at the end of a service or consultation, if requested?", question_es: "¿Cuál describe mejor una manera apropiada para que un esteticista elimine el maquillaje del rostro de un cliente al final de un servicio o consulta, si se solicita?", options: ["Using appropriate, gentle makeup removal products and techniques suited to the client's skin type, working carefully around the eye area, and following up with suitable skincare steps as needed", "Using any harsh product available, since the speed of removal matters more than how it affects the client's skin", "Scrubbing vigorously at the eye area regardless of how delicate that skin is", "Leaving all makeup in place and refusing to assist with removal under any circumstances, even if asked"], options_es: ["Usar productos y técnicas de eliminación de maquillaje apropiados y suaves adecuados para el tipo de piel del cliente, trabajando con cuidado alrededor del área de los ojos, y continuando con los pasos de cuidado de la piel adecuados según sea necesario", "Usar cualquier producto fuerte disponible, ya que la velocidad de eliminación importa más que cómo afecta a la piel del cliente", "Frotar vigorosamente el área de los ojos sin importar cuán delicada sea esa piel", "Dejar todo el maquillaje en su lugar y negarse a ayudar con la eliminación bajo cualquier circunstancia, incluso si se solicita"], explanation: "Gentle, appropriate makeup removal — using products suited to the client's skin type, taking extra care around the delicate eye area, and following with suitable skincare as needed — protects the client's skin and comfort. Prioritizing speed over gentleness, being rough around the eyes, or refusing a reasonable request to help with removal would all be inappropriate." },
  { id: 516, question: "A client asks the esthetician to explain, in approachable terms, what 'undertone' means and why it matters when choosing makeup colors. An accurate, appropriately scoped explanation would describe undertone as:", question_es: "Un cliente le pide al esteticista que explique, en términos accesibles, qué significa 'subtono' y por qué importa al elegir los colores del maquillaje. Una explicación precisa y con el alcance apropiado describiría el subtono como:", options: ["A subtle quality beneath the surface tone of the skin (often described in terms like cool, warm, or neutral) that can influence which makeup shades tend to look most harmonious and natural on a given person", "An official medical classification that only licensed physicians are permitted to determine for any individual", "A permanent, unchangeable category that makes it impossible for any two people to ever wear the same makeup shade", "A marketing term invented purely to sell more products, with no real connection to how makeup colors appear on skin"], options_es: ["Una cualidad sutil debajo del tono superficial de la piel (a menudo descrita en términos como frío, cálido o neutro) que puede influir en qué tonos de maquillaje tienden a verse más armoniosos y naturales en una persona determinada", "Una clasificación médica oficial que solo los médicos con licencia pueden determinar para cualquier individuo", "Una categoría permanente e inmutable que hace imposible que dos personas alguna vez usen el mismo tono de maquillaje", "Un término de marketing inventado únicamente para vender más productos, sin ninguna conexión real con cómo aparecen los colores del maquillaje en la piel"], explanation: "Undertone refers to the subtle quality beneath the surface color of the skin — commonly described as cool, warm, or neutral — and can meaningfully influence how different makeup shades appear on an individual. Explaining this concept in approachable, accurate terms helps clients understand why certain shades may look more harmonious on them, without overstating it as a rigid medical classification or dismissing it as mere marketing." },
  { id: 517, question: "Which best describes a responsible approach for an esthetician when applying makeup over an area of the client's skin that has a recent minor blemish or breakout?", question_es: "¿Cuál describe mejor un enfoque responsable para un esteticista al aplicar maquillaje sobre un área de la piel del cliente que tiene una lesión o brote menor reciente?", options: ["Using clean tools and gentle technique, applying only an appropriate amount of suitable product to minimize the appearance of the area without aggravating it, and avoiding excessive manipulation of the affected skin", "Pressing firmly and repeatedly on the area to physically force the product to cover it completely", "Using the same brush or applicator on the affected area as on the rest of the face without any extra care or cleaning", "Refusing to provide any service at all if the esthetician notices any minor blemish anywhere on the client's face"], options_es: ["Usar herramientas limpias y una técnica suave, aplicar solo una cantidad apropiada de producto adecuado para minimizar la apariencia del área sin agravarla, y evitar la manipulación excesiva de la piel afectada", "Presionar con fuerza y repetidamente sobre el área para forzar físicamente que el producto la cubra por completo", "Usar la misma brocha o aplicador en el área afectada que en el resto del rostro sin ningún cuidado o limpieza adicional", "Negarse a brindar cualquier servicio si el esteticista nota cualquier lesión menor en cualquier parte del rostro del cliente"], explanation: "When working near a minor blemish, a careful esthetician uses clean tools, applies product gently and only as needed, and avoids pressing on or over-manipulating the area — which could aggravate it or spread bacteria to other parts of the face. This balanced, careful approach allows the service to proceed comfortably and hygienically without unnecessarily refusing service over a minor, common skin occurrence." },
  { id: 518, question: "Which best describes an appropriate way for an esthetician to use color theory (such as the relationship between complementary colors) when helping a client choose makeup to enhance their eye color?", question_es: "¿Cuál describe mejor una manera apropiada para que un esteticista use la teoría del color (como la relación entre los colores complementarios) para ayudar a un cliente a elegir maquillaje que realce el color de sus ojos?", options: ["Explaining, in approachable terms, how certain shades positioned opposite the client's eye color on the color wheel may help that eye color appear more vivid, while remaining open to the client's own preferences and final choice", "Insisting that only one specific eyeshadow color can ever be worn by people with a particular eye color, with no other option considered acceptable", "Telling the client that color theory is purely an artistic concept with no practical relevance to makeup application", "Choosing colors at random without any explanation, since the client would not be able to understand any reasoning behind the choice"], options_es: ["Explicar, en términos accesibles, cómo ciertos tonos ubicados opuestos al color de ojos del cliente en la rueda de colores pueden ayudar a que ese color de ojos aparezca más vívido, mientras se permanece abierto a las preferencias propias del cliente y su elección final", "Insistir en que solo un color específico de sombra de ojos puede ser usado alguna vez por personas con un color de ojos particular, sin considerar aceptable ninguna otra opción", "Decirle al cliente que la teoría del color es puramente un concepto artístico sin relevancia práctica para la aplicación de maquillaje", "Elegir colores al azar sin ninguna explicación, ya que el cliente no podría entender ningún razonamiento detrás de la elección"], explanation: "Sharing accessible color theory concepts — such as how shades opposite a person's eye color on the color wheel can help that eye color appear more vivid — gives the client useful, empowering information they can use in deciding what they'd like to try. This collaborative approach respects the client's preferences and final say, rather than presenting a single rigid rule, dismissing the concept's relevance, or leaving the client without any explanation." },
  { id: 519, question: "Which best describes why an esthetician should perform a patch test before applying a new cosmetic product to a client's face, particularly if the client has a history of skin sensitivities?", question_es: "¿Cuál describe mejor por qué un esteticista debe realizar una prueba de parche antes de aplicar un nuevo producto cosmético en el rostro de un cliente, particularmente si el cliente tiene antecedentes de sensibilidades en la piel?", options: ["A patch test allows the esthetician to observe how the client's skin responds to a small amount of product in a less prominent area before applying it more broadly, helping reduce the risk of an unexpected reaction on visible facial skin", "Patch testing is solely a formality with no real bearing on whether a product might cause a reaction on a client's face", "Patch testing guarantees with complete certainty that no reaction of any kind could ever occur once the product is used elsewhere", "Patch testing should be skipped for any client who states they have used similar products before without any issue"], options_es: ["Una prueba de parche le permite al esteticista observar cómo responde la piel del cliente a una pequeña cantidad de producto en un área menos prominente antes de aplicarlo más ampliamente, ayudando a reducir el riesgo de una reacción inesperada en la piel facial visible", "La prueba de parche es únicamente una formalidad sin ninguna relación real con si un producto podría causar una reacción en el rostro de un cliente", "La prueba de parche garantiza con completa certeza que no podría ocurrir ningún tipo de reacción una vez que el producto se use en otra parte", "La prueba de parche debe omitirse para cualquier cliente que indique que ha usado productos similares antes sin ningún problema"], explanation: "A patch test involves applying a small amount of a new product to a less visible area and observing the skin's response before broader application. While it cannot guarantee that no reaction will ever occur, it is a reasonable, professionally responsible step that can help reduce the risk of an unexpected reaction appearing on more visible facial skin — particularly valuable when a client has a known history of sensitivities, and worthwhile even when a client reports no prior issues with similar products." },
  { id: 520, question: "Which best describes an appropriate professional response if a client becomes visibly upset or emotional during a makeup consultation while discussing their appearance?", question_es: "¿Cuál describe mejor una respuesta profesional apropiada si un cliente se muestra visiblemente molesto o emocional durante una consulta de maquillaje mientras habla sobre su apariencia?", options: ["Responding with empathy and patience, giving the client space to express themselves, gently refocusing on how the esthetician can help them feel more confident, and adjusting the pace of the conversation as needed", "Ignoring the client's emotional response entirely and continuing with the planned consultation script without any acknowledgment", "Telling the client that their feelings about their own appearance are not a reasonable topic to bring up during a consultation", "Ending the appointment immediately without any further conversation or support"], options_es: ["Responder con empatía y paciencia, darle al cliente espacio para expresarse, reenfocar suavemente en cómo el esteticista puede ayudarlo a sentirse más seguro, y ajustar el ritmo de la conversación según sea necesario", "Ignorar por completo la respuesta emocional del cliente y continuar con el guion de consulta planificado sin ningún reconocimiento", "Decirle al cliente que sus sentimientos sobre su propia apariencia no son un tema razonable para mencionar durante una consulta", "Terminar la cita de inmediato sin ninguna conversación o apoyo adicional"], explanation: "Conversations about appearance can sometimes touch on sensitive feelings. Responding with empathy, patience, and a gentle, supportive redirection toward how the service can help the client feel good about themselves reflects emotional intelligence and professionalism — far more appropriate than ignoring the moment, dismissing the client's feelings, or abruptly ending the interaction." },
  { id: 521, question: "A client asks the esthetician to explain, in general terms, why the same lipstick shade might look different on different people. An accurate, appropriately scoped explanation would note that:", question_es: "Un cliente le pide al esteticista que explique, en términos generales, por qué el mismo tono de lápiz labial podría verse diferente en diferentes personas. Una explicación precisa y con el alcance apropiado señalaría que:", options: ["Differences in an individual's natural lip color, undertone, and skin tone can all influence how a particular shade appears once applied, which is part of why trying a shade on oneself can be more informative than judging it on someone else", "The same lipstick shade always produces a chemically identical visual result on every single person regardless of any individual differences", "Lipstick shades change their actual chemical color formula depending on who purchases the product", "There is no possible explanation for why the same product might look different on different individuals"], options_es: ["Las diferencias en el color natural de los labios, el subtono y el tono de piel de un individuo pueden influir en cómo aparece un tono particular una vez aplicado, lo cual es parte de la razón por la que probarse un tono uno mismo puede ser más informativo que juzgarlo en otra persona", "El mismo tono de lápiz labial siempre produce un resultado visual químicamente idéntico en cada persona sin importar ninguna diferencia individual", "Los tonos de lápiz labial cambian su fórmula química de color real dependiendo de quién compre el producto", "No existe ninguna explicación posible de por qué el mismo producto podría verse diferente en diferentes individuos"], explanation: "A cosmetic shade interacts with an individual's natural lip color, undertone, and overall skin tone, which is why the same product can look noticeably different from person to person. Sharing this simple, accurate idea helps explain a common observation clients make and gently encourages them to try shades on themselves rather than assuming a look they saw on someone else will translate identically." },
  { id: 522, question: "Which best describes the purpose of using a setting spray as a final step in a facial makeup application?", question_es: "¿Cuál describe mejor el propósito de usar un spray fijador como paso final en una aplicación de maquillaje facial?", options: ["To help meld the layers of makeup together, reduce the appearance of powdery texture, and support longer-lasting wear, depending on the specific product and the client's preferences", "To permanently weld the makeup to the skin so that no cleansing product will ever remove it", "To replace the need for any primer, foundation, or other base products used earlier in the application", "To provide guaranteed, complete protection against all forms of sun exposure for the rest of the day"], options_es: ["Ayudar a fusionar las capas del maquillaje, reducir la apariencia de textura polvorienta, y favorecer una mayor duración, dependiendo del producto específico y las preferencias del cliente", "Soldar permanentemente el maquillaje a la piel para que ningún producto de limpieza pueda eliminarlo jamás", "Reemplazar la necesidad de cualquier primer, base u otros productos base usados anteriormente en la aplicación", "Proporcionar una protección garantizada y completa contra todas las formas de exposición solar durante el resto del día"], explanation: "A setting spray is typically used as a finishing step to help blend the layers of a makeup look together, soften any powdery texture, and extend wear time — its specific benefits depending on the product formula and the client's preferences and routine. It is not a permanent bonding agent, a substitute for the earlier base steps, or a reliable source of sun protection on its own." },
  { id: 523, question: "Which best illustrates an esthetician appropriately adapting a facial makeup application to suit an individual client's mature skin?", question_es: "¿Cuál ilustra mejor a un esteticista adaptando apropiadamente una aplicación de maquillaje facial para adecuarse a la piel madura de un cliente individual?", options: ["Considering how factors such as changes in skin texture and moisture levels may interact with certain formulas and techniques, and adjusting product choices and application methods accordingly while honoring the client's preferences", "Applying the exact same heavy-coverage technique used for any other client without any consideration of how it may interact with the client's individual skin", "Assuming that mature clients have no interest in or use for any makeup application services", "Telling the client that no makeup products or techniques can ever be appropriately adapted for any individual characteristic"], options_es: ["Considerar cómo factores como los cambios en la textura de la piel y los niveles de humedad pueden interactuar con ciertas fórmulas y técnicas, y ajustar las elecciones de productos y los métodos de aplicación en consecuencia, honrando las preferencias del cliente", "Aplicar exactamente la misma técnica de cobertura pesada usada para cualquier otro cliente sin ninguna consideración de cómo puede interactuar con la piel individual del cliente", "Asumir que los clientes maduros no tienen ningún interés ni uso para ningún servicio de aplicación de maquillaje", "Decirle al cliente que ningún producto o técnica de maquillaje puede adaptarse apropiadamente a ninguna característica individual"], explanation: "Skin can change in texture and other characteristics over time, and a thoughtful esthetician considers how these individual factors may interact with different formulas (for example, how certain textures or finishes settle into the skin) and adjusts product and technique choices accordingly — always working collaboratively with the client's own preferences. This individualized approach reflects genuine skill, in contrast to a one-size-fits-all method or assumptions about what any group of clients might want." },
  { id: 524, question: "A client asks the esthetician for general guidance on how long they can typically expect an opened mascara product to remain suitable for use before it should be replaced. Which response best reflects sound, appropriately scoped professional guidance?", question_es: "Un cliente le pregunta al esteticista por orientación general sobre cuánto tiempo puede esperar típicamente que un producto de máscara de pestañas abierto permanezca adecuado para su uso antes de que deba reemplazarse. ¿Cuál respuesta refleja mejor una orientación profesional sólida y con el alcance apropiado?", options: ["Sharing general guidance that mascara is often recommended for replacement after a few months of use due to the way it is stored and applied near the eyes, while encouraging the client to also follow the manufacturer's specific guidance and to discontinue use if they notice any change in texture, smell, or any irritation", "Telling the client that an opened mascara remains perfectly safe and effective for use indefinitely with no need to ever consider replacing it", "Insisting on one single, universally exact expiration date that applies identically to every mascara product ever made, regardless of brand or formula", "Advising the client that questions about product shelf life are never appropriate to discuss during a professional consultation"], options_es: ["Compartir una orientación general de que a menudo se recomienda reemplazar la máscara de pestañas después de algunos meses de uso debido a la forma en que se almacena y se aplica cerca de los ojos, mientras se anima al cliente a también seguir las indicaciones específicas del fabricante y a descontinuar el uso si nota algún cambio en la textura, el olor o cualquier irritación", "Decirle al cliente que una máscara de pestañas abierta permanece perfectamente segura y eficaz para su uso indefinidamente sin necesidad de considerar nunca su reemplazo", "Insistir en una única fecha de vencimiento exacta y universal que se aplique de manera idéntica a cada producto de máscara de pestañas jamás fabricado, sin importar la marca o la fórmula", "Aconsejar al cliente que las preguntas sobre la vida útil del producto nunca son apropiadas para discutir durante una consulta profesional"], explanation: "Products used near the eyes, like mascara, are commonly associated with general replacement guidance (often discussed in terms of a few months of regular use) due to repeated exposure to air, applicators, and the sensitive eye area. Sharing this kind of general, commonly cited guidance — while pointing the client toward manufacturer instructions and encouraging attention to changes in texture, smell, or irritation — is helpful and appropriately scoped, unlike claiming indefinite safety, asserting one rigid universal date, or refusing to engage with a reasonable practical question." },
  { id: 525, question: "Which best summarizes the overall professional approach an esthetician should take when providing a facial makeup application service — from consultation through completion?", question_es: "¿Cuál resume mejor el enfoque profesional general que un esteticista debe adoptar al brindar un servicio de aplicación de maquillaje facial — desde la consulta hasta la finalización?", options: ["Conducting a thoughtful consultation to understand the client's preferences, skin type, and the occasion; selecting appropriate, well-matched products and techniques; using sanitary practices and tools throughout; communicating honestly and respectfully at every step; and helping the client feel confident in the finished look", "Choosing the same products, colors, and techniques for every client regardless of their individual skin, preferences, or the occasion", "Prioritizing the fastest possible completion time above accuracy, sanitation, and the client's comfort or preferences", "Avoiding any conversation with the client so personal opinions cannot influence the service in any way"], options_es: ["Realizar una consulta reflexiva para entender las preferencias del cliente, su tipo de piel y la ocasión; seleccionar productos y técnicas apropiados y bien combinados; usar prácticas e instrumentos sanitarios durante todo el proceso; comunicarse con honestidad y respeto en cada paso; y ayudar al cliente a sentirse seguro con el look terminado", "Elegir los mismos productos, colores y técnicas para cada cliente sin importar su piel individual, sus preferencias o la ocasión", "Priorizar el tiempo de finalización más rápido posible por encima de la precisión, el saneamiento y la comodidad o las preferencias del cliente", "Evitar cualquier conversación con el cliente para que las opiniones personales no puedan influir en el servicio de ninguna manera"], explanation: "A sound, professional approach to facial makeup application weaves together every stage: a genuine consultation that uncovers the client's individual preferences, skin type, and the context for the look; careful selection of well-suited products, colors, and techniques; consistent sanitary practices; honest, respectful communication throughout; and a final result that helps the client feel confident and satisfied. This individualized, safety-and-trust-centered approach — not uniformity, speed, or avoidance of conversation — is what defines quality esthetic makeup artistry." },
]

let out = readFileSync(FILE, 'utf8')
out += FM.map(fmt).join('\n') + '\n'
out += ']\n'
writeFileSync(FILE, out, 'utf8')
console.log(`Appended ${FM.length} Facial Makeup (ids ${FM[0].id}–${FM[FM.length-1].id}) and closed array`)
